package webui

// stylesBase is the reset, typography, focus and visibility baseline shared by every page.
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesBase = `*{box-sizing:border-box}html{height:100%;scroll-behavior:smooth}body{min-width:320px;min-height:100%;margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,"Noto Sans SC","PingFang SC","Microsoft YaHei",system-ui,sans-serif;font-size:14px;line-height:1.55;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button{cursor:pointer}form,h1,h2,h3,h4,p{margin:0}code,pre{font-family:"SFMono-Regular",Consolas,"Liberation Mono",monospace}svg{display:block}details>summary{list-style:none}details>summary::-webkit-details-marker{display:none}a,button,input,select,textarea,summary{transition:background-color .16s ease,border-color .16s ease,color .16s ease,box-shadow .16s ease,transform .16s ease}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}:is(a,button,summary):focus-visible{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 16%,transparent)}.visually-hidden{position:absolute!important;width:1px!important;height:1px!important;margin:-1px!important;padding:0!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.eyebrow{color:var(--accent);font-size:11px;font-weight:750;letter-spacing:0}.muted-text{color:var(--muted)}::-webkit-scrollbar{width:10px;height:10px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:var(--line-2);border-radius:8px;border:3px solid transparent;background-clip:content-box}::-webkit-scrollbar-thumb:hover{background:color-mix(in srgb,var(--line-2) 70%,var(--accent));background-clip:content-box}
`
